const body = $json.body || $json;
let sender = body?.whatsappInboundMessage?.from || body?.from || '';
let message = body?.whatsappInboundMessage?.text?.body || body?.text?.body;

if (!message && body?.whatsappInboundMessage?.interactive) {
  const interact = body.whatsappInboundMessage.interactive;
  message = interact.list_reply?.id || interact.button_reply?.id || interact.list_reply?.title || interact.button_reply?.title;
}

message = message || 'Hola';
let name = body?.whatsappInboundMessage?.customerProfile?.name || 'Cliente';

return {
  sender: String(sender).trim(),
  message: String(message).trim(),
  name: String(name).trim(),
  shop_slug: 'demo'
};

const msg = $('Extract Message').item.json;
const ctxRaw = $('Get Shop Context').item.json;
const ctx = Array.isArray(ctxRaw) ? ctxRaw[0] : ctxRaw;
const sessRaw = $('Get Session').item.json;
const sess = Array.isArray(sessRaw) ? sessRaw[0] : sessRaw;

const services = (ctx?.services || '').split(',').map(s => s.trim()).filter(Boolean);
const professionals = (ctx?.professionals || '').split(',').map(s => s.trim()).filter(Boolean);

const today = new Date();
const pad = n => String(n).padStart(2, '0');
const todayStr = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;

return {
  userMessage: msg.message,
  userName: msg.name,
  sender: msg.sender,
  shopName: ctx?.shop_name || 'Peluquería',
  services: services,
  professionals: professionals,
  currentState: sess?.current_state || 'IDLE',
  currentIntent: sess?.intent || null,
  sessionService: sess?.service || null,
  sessionProfessional: sess?.professional || null,
  sessionDate: sess?.preferred_date || null,
  sessionTime: sess?.preferred_time || null,
  todayDate: todayStr
};

