// =====================================================
// STATE MACHINE v10: Final Fix
// =====================================================

const prevContext = $('Prepare AI Context').item.json;
const aiOutput = $json.output || $json.text || $json.response?.text || '{}';

// Parse AI response
let parsed;
try {
  const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
  parsed = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
} catch (e) {
  parsed = { intent: 'OTHER', extracted: {}, naturalResponse: '' };
}

const aiIntent = parsed.intent || 'OTHER';
const extracted = parsed.extracted || {};
let naturalResponse = parsed.naturalResponse || '';

// Start with session values
let service = prevContext.sessionService;
let professional = prevContext.sessionProfessional;
let preferredDate = prevContext.sessionDate;
let preferredTime = prevContext.sessionTime;
let currentState = prevContext.currentState || 'IDLE';
let intent = prevContext.currentIntent;

const userMessage = prevContext.userMessage;
const msgLower = userMessage.toLowerCase();

// CANCEL takes priority if user says cancel
if (msgLower.includes('cancelar') || aiIntent === 'CANCEL') {
  intent = 'CANCEL';
  // Reset booking data when switching to cancel
  service = null;
  professional = null;
  preferredDate = null;
  preferredTime = null;
} else if (aiIntent === 'GREET' && currentState === 'IDLE') {
  intent = 'GREET';
} else if (aiIntent === 'BOOK' || currentState.startsWith('AWAITING_')) {
  intent = 'BOOK';

  // Override with AI-extracted values if present
  if (extracted.service) service = extracted.service;
  if (extracted.professional) professional = extracted.professional;
  if (extracted.date) preferredDate = extracted.date;
  if (extracted.time) preferredTime = extracted.time;

  // Direct matching for list selections
  for (const s of prevContext.services) {
    if (userMessage === s || msgLower === s.toLowerCase()) {
      service = s;
      break;
    }
  }

  for (const p of prevContext.professionals) {
    if (userMessage === p || msgLower === p.toLowerCase()) {
      professional = p;
      break;
    }
  }

  // Date pattern
  if (/^\d{4}-\d{2}-\d{2}$/.test(userMessage)) {
    preferredDate = userMessage;
  }

  // Time pattern
  if (/^\d{1,2}:\d{2}(:\d{2})?$/.test(userMessage)) {
    preferredTime = userMessage.length === 5 ? userMessage + ':00' : userMessage;
  }
}

const sender = prevContext.sender;
const userName = prevContext.userName;
const shopName = prevContext.shopName;
const services = prevContext.services;
const professionals = prevContext.professionals;

// Generate next 7 days
const days = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const months = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
const today = new Date();
const pad = n => String(n).padStart(2, '0');

const dateOptions = [];
for (let i = 0; i < 7; i++) {
  const d = new Date(today);
  d.setDate(d.getDate() + i);
  const iso = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  const dayName = i === 0 ? 'Hoy' : (i === 1 ? 'Mañana' : days[d.getDay()]);
  const label = `${dayName} ${d.getDate()} ${months[d.getMonth()]}`;
  dateOptions.push({ id: iso, title: label, description: '' });
}

// =====================================================
// Determine response
// =====================================================
let response = null;
let routeTo = 0;

if (intent === 'CANCEL') {
  currentState = 'AWAITING_CANCEL_SELECTION';
  routeTo = 3; // CANCEL_FLOW - fetch appointments

} else if (intent === 'GREET') {
  response = {
    type: 'text',
    text: { body: naturalResponse || `¡Hola! 👋 Bienvenido a *${shopName}*. ¿Querés reservar o cancelar un turno?` }
  };
  currentState = 'IDLE';
  intent = null;
  service = null;
  professional = null;
  preferredDate = null;
  preferredTime = null;

} else if (intent === 'BOOK') {
  if (!service) {
    const rows = services.slice(0, 10).map(s => ({ id: s, title: s.slice(0, 24), description: '' }));
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '💇 Nuestros Servicios' },
        body: { text: naturalResponse || '¿Qué servicio te gustaría? 😊' },
        footer: { text: shopName },
        action: { button: 'Ver Servicios', sections: [{ title: 'Servicios', rows: rows }] }
      }
    };
    currentState = 'AWAITING_SERVICE';

  } else if (!professional) {
    const rows = professionals.slice(0, 10).map(p => ({ id: p, title: p.slice(0, 24), description: '' }));
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '💈 Nuestros Profesionales' },
        body: { text: naturalResponse || `Elegiste *${service}*. ¿Con quién querés?` },
        footer: { text: shopName },
        action: { button: 'Ver Profesionales', sections: [{ title: 'Profesionales', rows: rows }] }
      }
    };
    currentState = 'AWAITING_PROFESSIONAL';

  } else if (!preferredDate) {
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '📅 Elegí una Fecha' },
        body: { text: naturalResponse || `*${service}* con *${professional}*. ¿Qué día?` },
        footer: { text: shopName },
        action: { button: 'Ver Fechas', sections: [{ title: 'Próximos días', rows: dateOptions }] }
      }
    };
    currentState = 'AWAITING_DATE';

  } else if (!preferredTime) {
    currentState = 'AWAITING_TIME';
    routeTo = 1; // FETCH_TIMES

  } else {
    routeTo = 2; // BOOK_NOW
  }

} else {
  response = {
    type: 'text',
    text: { body: naturalResponse || `¡Hola! 👋 Puedo ayudarte a:\n\n• *Reservar* un turno\n• *Cancelar* un turno\n\n¿Qué te gustaría hacer?` }
  };
  currentState = 'IDLE';
}

return {
  routeTo: routeTo,
  response: response,
  sender: sender,
  updateSession: {
    current_state: currentState || 'IDLE',
    intent: intent || '',
    service: service || '',
    professional: professional || '',
    preferred_date: preferredDate || '',
    preferred_time: preferredTime || ''
  },
  context: {
    sender: sender,
    userName: userName,
    shopName: shopName,
    service: service,
    professional: professional,
    preferredDate: preferredDate,
    preferredTime: preferredTime
  }
};

const slotsRaw = $json;
const context = $('Pass Data').item.json.context;
const sender = $('Pass Data').item.json.sender;

console.log('Raw slots:', JSON.stringify(slotsRaw));

// Ensure slots is an array
const slots = Array.isArray(slotsRaw) ? slotsRaw : (slotsRaw ? [slotsRaw] : []);

if (slots.length === 0 || slots[0]?.error) {
  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `😕 No hay horarios disponibles para esa fecha. ¿Probamos otro día?` }
    }
  };
}

const rows = slots.slice(0, 10).map((slot, i) => {
  let time = '';

  // Handle different slot formats
  if (typeof slot === 'string') {
    time = slot.includes('T') ? slot.substring(11, 16) : slot.substring(0, 5);
  } else if (slot.start_time) {
    time = slot.start_time.includes('T') ? slot.start_time.substring(11, 16) : slot.start_time.substring(0, 5);
  } else if (slot.time) {
    time = String(slot.time).substring(0, 5);
  } else if (slot.slot) {
    time = String(slot.slot).substring(0, 5);
  } else {
    // Try to find any time-like property
    const keys = Object.keys(slot);
    for (const k of keys) {
      const val = String(slot[k]);
      if (val.match(/^\d{2}:\d{2}/)) {
        time = val.substring(0, 5);
        break;
      }
    }
    if (!time) time = `Horario ${i + 1}`;
  }

  return { id: time + ':00', title: time, description: '' };
});

const dateParts = context.preferredDate.split('-');
const formattedDate = `${dateParts[2]}/${dateParts[1]}`;

return {
  sender: sender,
  response: {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: '🕐 Horarios Disponibles' },
      body: { text: `📅 *${formattedDate}* con *${context.professional}*\n\n¿A qué hora te viene bien?` },
      footer: { text: context.shopName },
      action: { button: 'Ver Horarios', sections: [{ title: 'Horarios', rows: rows }] }
    }
  }
};

const result = $json;
const context = $('Pass Data').item.json.context;
const sender = $('Pass Data').item.json.sender;

if (result.success) {
  const dateParts = context.preferredDate.split('-');
  const formattedDate = `${dateParts[2]}/${dateParts[1]}/${dateParts[0]}`;
  const formattedTime = context.preferredTime.substring(0, 5);

  return {
    sender: sender,
    resetSession: true,
    response: {
      type: 'text',
      text: { body: `✅ *¡Reserva Confirmada!*\n\n💇 *Servicio:* ${context.service}\n💈 *Profesional:* ${context.professional}\n📅 *Fecha:* ${formattedDate} a las ${formattedTime}\n\n📍 *Lugar:* ${context.shopName}\n\n¡Te esperamos! 🎉\n\n_Escribí "Hola" para hacer otra reserva._` }
    }
  };
} else {
  const errorMsg = result.error || '';
  let userMsg = '❌ Hubo un problema.';

  if (errorMsg.includes('idx_unique_active_appointment') || errorMsg.includes('duplicate key')) {
    userMsg = `⚠️ Ya hay un turno reservado en ese horario con ${context.professional}.\n\n¿Querés elegir otro horario o profesional?`;
  } else {
    userMsg = `❌ ${errorMsg || 'Hubo un problema.'}\n\n¿Probamos otro horario?`;
  }

  return {
    sender: sender,
    resetSession: false,
    response: {
      type: 'text',
      text: { body: userMsg }
    }
  };
}

const appointmentsRaw = $json;
const context = $('Pass Data').item.json.context;
const sender = $('Pass Data').item.json.sender;

// Ensure appointments is an array
const appointments = Array.isArray(appointmentsRaw) ? appointmentsRaw : (appointmentsRaw ? [appointmentsRaw] : []);

if (appointments.length === 0 || appointments[0]?.error) {
  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `No tenés turnos pendientes. 😊 ¿Querés reservar uno?` }
    }
  };
}

const rows = appointments.slice(0, 10).map(apt => {
  const date = apt.appointment_date || (apt.start_time ? apt.start_time.substring(0, 10) : '');
  const time = apt.appointment_time || (apt.start_time ? apt.start_time.substring(11, 16) : '');
  const dateParts = date.split('-');
  const shortDate = dateParts.length === 3 ? `${dateParts[2]}/${dateParts[1]}` : date;

  return {
    id: String(apt.appointment_id || apt.id),
    title: `${shortDate} ${time}`.slice(0, 24),
    description: (apt.service_name || 'Servicio').slice(0, 72)
  };
});

return {
  sender: sender,
  response: {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: '📋 Tus Turnos' },
      body: { text: 'Seleccioná el turno que querés cancelar:' },
      footer: { text: context.shopName },
      action: { button: 'Ver Turnos', sections: [{ title: 'Turnos', rows: rows }] }
    }
  }
};
